_STYLE = r"""
:root{color-scheme:dark;--bg:#09100d;--panel:#111a16;--panel2:#16211c;--line:#2a3b32;--text:#f0f5ef;--muted:#9eada4;--green:#baf45a;--teal:#67dec9;--red:#ff746d;--amber:#f5c96b;--shadow:0 22px 55px rgba(0,0,0,.22)}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#15251d 0,transparent 34rem),var(--bg);color:var(--text);font:15px/1.5 Inter,ui-sans-serif,system-ui,sans-serif}a{color:var(--teal)}
header{position:sticky;top:0;z-index:10;background:rgba(9,16,13,.92);backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}.bar{max-width:1240px;margin:auto;padding:14px 28px;display:flex;align-items:center;gap:28px}.brand{color:var(--text);font-weight:800;text-decoration:none;letter-spacing:.02em}.brand span{color:var(--green)}nav{display:flex;gap:6px;flex-wrap:wrap}nav a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:9px}nav a:hover,nav a.active{color:var(--text);background:var(--panel2)}.revision{margin-left:auto;color:var(--muted);font:12px ui-monospace,monospace}
main{max-width:1240px;margin:auto;padding:42px 28px 80px}.eyebrow{color:var(--green);font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.page-head{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:28px}.page-head h1{font-size:clamp(30px,5vw,48px);line-height:1.05;margin:6px 0}.page-head p{max-width:720px;color:var(--muted);margin:0}.grid{display:grid;gap:18px}.grid.two{grid-template-columns:repeat(auto-fit,minmax(360px,1fr))}.grid.three{grid-template-columns:repeat(auto-fit,minmax(220px,1fr))}.card{background:linear-gradient(145deg,var(--panel),#0d1511);border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:var(--shadow)}.card h2,.card h3{margin:0 0 6px}.card>p,.hint{color:var(--muted)}.stat strong{display:block;font-size:34px;color:var(--green)}.stat span{color:var(--muted)}
details{border:1px solid var(--line);border-radius:13px;background:rgba(0,0,0,.12);margin:12px 0}summary{cursor:pointer;padding:16px 18px;font-weight:750}details>form,details>.detail-body{padding:2px 18px 18px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.field.full{grid-column:1/-1}.field label,.field>span{display:block;color:var(--muted);font-size:12px;font-weight:700;margin:0 0 6px;text-transform:uppercase;letter-spacing:.06em}input,select,textarea{width:100%;border:1px solid #3a4b42;border-radius:9px;background:#09100d;color:var(--text);padding:10px 11px;font:inherit}textarea{min-height:88px;resize:vertical;font-family:ui-monospace,monospace}input:focus,select:focus,textarea:focus{outline:2px solid rgba(103,222,201,.28);border-color:var(--teal)}input[readonly]{opacity:.7}.checks{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px}.check{display:flex;gap:9px;align-items:center;padding:9px;border:1px solid var(--line);border-radius:9px;color:var(--text)}.check input{width:auto}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:18px}button,.button{border:0;border-radius:9px;background:var(--green);color:#10150f;padding:10px 15px;font-weight:800;cursor:pointer;text-decoration:none}button:hover,.button:hover{filter:brightness(1.08)}button:disabled{cursor:wait;opacity:.55}button.secondary,.button.secondary{background:#26352d;color:var(--text)}button.danger{background:#4c2827;color:#ffd8d5}.message{min-height:24px;margin:14px 0;color:var(--teal)}.message.error{color:var(--red)}.result{white-space:pre-wrap;overflow:auto;background:#07100b;border:1px solid var(--line);border-radius:10px;padding:12px;color:#cfe4d7;max-height:340px}
table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);font-size:12px;text-transform:uppercase}code{font-family:ui-monospace,monospace}.status{font-weight:800}.status.passed{color:var(--green)}.status.failed,.status.error{color:var(--red)}.status.running,.status.queued{color:var(--teal)}.table-actions{display:flex;gap:8px;flex-wrap:wrap}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 8px;color:var(--muted);font-size:12px}.pill.warn{color:var(--amber);border-color:#725d31}.pr-filter{display:flex;align-items:end;justify-content:space-between;gap:14px;margin-top:18px;padding:14px 16px;border:1px solid var(--line);border-radius:12px;background:rgba(103,222,201,.03)}.pr-filter .field{min-width:min(320px,100%)}.pr-filter>span{color:var(--muted);font-size:12px}.pr-card{border-left:3px solid var(--teal);padding:14px 16px}.pr-title{font-size:15px;font-weight:800;color:var(--text);text-decoration:none}.pr-meta{color:var(--muted);display:flex;gap:10px;flex-wrap:wrap;margin:4px 0 8px;font-size:12px}.danger-note{border:1px solid var(--line);background:rgba(103,222,201,.04);color:var(--muted);border-radius:8px;padding:7px 9px;font-size:12px}.pr-card .check{padding:6px 8px;font-size:12px}.pr-card .actions{margin-top:8px}.pr-pagination{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:14px;padding:12px 14px;border:1px solid var(--line);border-radius:10px;color:var(--muted)}.pr-pagination .actions{margin:0}.empty{color:var(--muted);padding:28px;text-align:center;border:1px dashed var(--line);border-radius:12px}.yaml{min-height:620px}.photo{max-width:220px;max-height:150px;border-radius:10px;border:1px solid var(--line)}
@media(max-width:700px){.bar{padding:12px 16px;align-items:flex-start;flex-direction:column;gap:8px}.revision{margin-left:0}.page-head{align-items:start;flex-direction:column}main{padding:28px 16px}.fields{grid-template-columns:1fr}.grid.two{grid-template-columns:1fr}}
"""


_SCRIPT = r"""
'use strict';
const boot=JSON.parse(document.getElementById('bootstrap').textContent);
let config=boot.config, revision=boot.revision, etag=boot.etag, bearerToken='', pullRequests=null, allPullRequests=[], pullRequestPage=1, pullContributorFilter='', pullRepository='', manualRepository='', manualGate='', central=boot.central||{};
const PR_PAGE_SIZE=10;
const app=document.getElementById('app');
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const clone=value=>JSON.parse(JSON.stringify(value));
const lines=value=>String(value??'').split(/[\n,]/).map(v=>v.trim()).filter(Boolean);
const checked=value=>value?'checked':'';
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${esc(label)}</span><input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value='',hint='')=>`<label class="field full"><span>${esc(label)}</span><textarea name="${esc(name)}">${esc(value)}</textarea>${hint?`<span class="hint">${esc(hint)}</span>`:''}</label>`;
const select=(label,name,items,value='',extra='')=>`<label class="field"><span>${esc(label)}</span><select name="${esc(name)}" ${extra}>${items.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
const checks=(label,name,items,selected=[])=>`<div class="field full"><span>${esc(label)}</span><div class="checks">${items.map(([id,text])=>`<label class="check"><input type="checkbox" name="${esc(name)}" value="${esc(id)}" ${selected.includes(id)?'checked':''}> ${esc(text)}</label>`).join('')||'<span class="hint">No choices configured yet.</span>'}</div></div>`;
const values=(form,name)=>[...form.querySelectorAll(`[name="${name}"]:checked`)].map(item=>item.value);
const integer=(form,name)=>{const value=form.elements[name]?.value.trim();return value?Number(value):undefined};
const pageHead=(title,description,action='')=>`<div class="page-head"><div><div class="eyebrow">${config.coordination?.mode==='central'?'Central coordination agent':config.coordination?.mode==='hybrid'?'Hybrid local + shared control':'Local control plane'}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${action}</div>`;
const hybridSharedCard=()=>config.coordination?.mode==='hybrid'?`<section class="card" style="margin-bottom:18px"><div class="eyebrow">SHARED STATUS DEFINITIONS</div><h2>Coordinated gates remain Status-owned</h2><p>This Lab also subscribes to <strong>${esc(config.coordination.central.subscriptions.gates.join(', '))}</strong>. Shared identities stay immutable in Status while execution uses this Lab's private bindings and leases.</p><a class="button secondary" href="${esc(config.coordination.central.base_url.replace(/\/$/,'')+'/projects')}" target="_blank" rel="noreferrer">Open Status projects</a></section>`:'';
const hybridSharedRunCard=()=>config.coordination?.mode==='hybrid'?`<section class="card" style="margin-bottom:18px"><div class="eyebrow">SHARED MANUAL RUN</div><h2>Run a coordinated gate on this Lab</h2><p>The local operator authorizes the request. Status freezes the shared definition and current source, then targets only this Lab.</p><form class="shared-run-form"><div class="fields">${select('Shared gate','shared_gate',config.coordination.central.subscriptions.gates.map(id=>[id,id]),config.coordination.central.subscriptions.gates[0]||'','required')}${select('Source type','shared_source_type',[['branch','Branch'],['pull_request','Pull request']],'branch','required')}${field('Branch or PR number','shared_source_value','main','text','required')}${checks('Testcode modules','shared_test_modules',Object.keys(config.bindings?.suite_requirements||{}).map(id=>[id,id]),Object.keys(config.bindings?.suite_requirements||{}))}</div><div class="actions"><button type="submit">Queue shared gate here</button><a class="button secondary" href="${esc(config.coordination.central.base_url.replace(/\/$/,'')+'/triggers')}" target="_blank" rel="noreferrer">Open Status Run</a></div><pre class="result" id="shared-run-result" hidden></pre></form></section>`:'';
const localModuleControls=()=>{const modules=config.gates?.[manualGate]?.test_modules||[];return checks('Testcode modules','manual_test_modules',modules.map(id=>[id,id]),modules)};
function neutralizeRunLanguage(){app.innerHTML=app.innerHTML.replaceAll('Run an untrusted PR','Run a pull request').replaceAll('This code is not from a trusted contributor. Confirm the PR and exact commit before giving it lab hardware.','Confirm this exact GitHub head before giving it Lab hardware.').replaceAll('No untrusted open pull requests target the watched base branches.','No open pull requests target the watched base branches.')}
function filteredPullRequests(){return pullContributorFilter?allPullRequests.filter(pr=>pr.contributor===pullContributorFilter):allPullRequests}
function showPullRequestPage(page){const filtered=filteredPullRequests(),pages=Math.max(1,Math.ceil(filtered.length/PR_PAGE_SIZE));pullRequestPage=Math.min(Math.max(1,page),pages);const start=(pullRequestPage-1)*PR_PAGE_SIZE;pullRequests=filtered.slice(start,start+PR_PAGE_SIZE);render()}
function pullRequestFilter(){if(!allPullRequests.length)return'';const contributors=[...new Set(allPullRequests.map(pr=>pr.contributor).filter(Boolean))].sort((a,b)=>a.localeCompare(b));return`<div class="pr-filter">${select('Contributor','pr_contributor_filter',[['','All contributors'],...contributors.map(name=>[name,'@'+name])],pullContributorFilter)}<span>${filteredPullRequests().length} matching · ${allPullRequests.length} total</span></div>`}
function pullRequestPagination(){const filtered=filteredPullRequests();if(filtered.length<=PR_PAGE_SIZE)return'';const pages=Math.ceil(filtered.length/PR_PAGE_SIZE),start=(pullRequestPage-1)*PR_PAGE_SIZE+1,end=Math.min(pullRequestPage*PR_PAGE_SIZE,filtered.length);return`<div class="pr-pagination"><span>${start}–${end} of ${filtered.length} matching · Page ${pullRequestPage} of ${pages}</span><div class="actions"><button class="secondary" type="button" data-action="pr-prev" ${pullRequestPage===1?'disabled':''}>Previous</button><button class="secondary" type="button" data-action="pr-next" ${pullRequestPage===pages?'disabled':''}>Next</button></div></div>`}
const setMessage=(text,error=false)=>{const target=document.getElementById('message');if(target){target.textContent=text;target.className='message'+(error?' error':'')}};
const showResult=(id,value)=>{const target=document.getElementById(id);if(target){target.hidden=false;target.textContent=typeof value==='string'?value:JSON.stringify(value,null,2)}};
function authHeaders(){const headers={};if(config.controller.auth_mode==='bearer'){if(!bearerToken)bearerToken=prompt('Local API bearer token')||'';if(!bearerToken)throw new Error('A bearer token is required');headers.Authorization='Bearer '+bearerToken}return headers}
async function request(path,options={}){const headers={...(options.mutate?authHeaders():{}),...(options.headers||{})};if(options.mutate&&options.etag!==false)headers['If-Match']=etag;let body=options.body;if(options.json!==undefined){headers['Content-Type']='application/json';body=JSON.stringify(options.json)}const response=await fetch(path,{method:options.method||'GET',headers,body});const text=await response.text();let payload=null;try{payload=text?JSON.parse(text):null}catch{payload=text}if(!response.ok){if(response.status===401)bearerToken='';throw new Error(payload?.detail||payload||`${response.status} ${response.statusText}`)}if(payload?.config){config=payload.config;revision=payload.revision;etag=response.headers.get('etag')||`"config-${revision}"`}return payload}
async function saveResource(path,id,value,create=false){return request(`/api/v1/${path}${create?'':'/'+encodeURIComponent(id)}`,{method:create?'POST':'PATCH',mutate:true,json:create?{id,value}:value})}
async function deleteResource(path,id){if(!confirm(`Delete ${id}? Configuration references may prevent this.`))return;await request(`/api/v1/${path}/${encodeURIComponent(id)}`,{method:'DELETE',mutate:true});render();setMessage(`Deleted ${id}`)}
function runRows(){return (boot.runs||[]).map(run=>{const retry=run.retryable?`<button type="button" data-action="retry-run" data-id="${esc(run.id)}">Retry</button>`:'';return `<tr><td>${esc(run.gate_id)}</td><td>${esc(run.trigger_type)}</td><td><code>${esc(run.commit_sha.slice(0,12))}</code>${run.pr_number?` <span class="pill">PR #${run.pr_number}</span>`:''}</td><td class="status ${esc(run.status)}">${esc(run.status)}</td><td><div class="table-actions"><button class="secondary" type="button" data-action="browse-artifacts" data-id="${esc(run.id)}">Local archive</button>${retry}</div></td></tr>`}).join('')||'<tr><td colspan="5">No gate runs yet.</td></tr>'}
function renderCentralOverview(){const bindings=Object.values(config.bindings?.suite_requirements||{}),statusUrl=config.coordination.central.base_url.replace(/\/$/,'');app.innerHTML=pageHead('Lab overview','Monitor the outbound central agent, private binding capacity, and durable recovery state.',`<a class="button" href="${esc(statusUrl+'/triggers')}" target="_blank" rel="noreferrer">Open central triggers</a>`)+`<div id="message" class="message"></div><div class="grid three"><section class="card stat"><strong>${bindings.length}</strong><span>private bindings</span></section><section class="card stat"><strong>${esc(central.active_leases||0)}</strong><span>active resource leases</span></section><section class="card stat"><strong>${esc(central.pending_executions||0)}</strong><span>pending executions</span></section></div><section class="card" style="margin-top:18px"><h2>Coordination status</h2><table><tbody><tr><th>Lab ID</th><td><code>${esc(config.coordination.central.lab_id)}</code></td></tr><tr><th>Subscribed gates</th><td>${esc((config.coordination.central.subscriptions?.gates||[]).join(', '))}</td></tr><tr><th>Agent</th><td class="status ${central.last_error?'error':'passed'}">${central.paused?'paused':central.last_error?'degraded':'active'}</td></tr><tr><th>Last cycle</th><td>${central.last_cycle_at?esc(new Date(central.last_cycle_at*1000).toISOString()):'Not observed yet'}</td></tr><tr><th>Last bounded error</th><td>${esc(central.last_error||'None')}</td></tr></tbody></table><div class="actions"><button type="button" data-action="${central.paused?'resume-central':'pause-central'}">${central.paused?'Resume new claims':'Pause new claims'}</button></div></section>`}
function renderOverview(){if(config.coordination?.mode==='central'){renderCentralOverview();return}app.innerHTML=pageHead('Lab overview','See the active configuration, recent hardware gate activity, and private local result archives.',`<a class="button" href="/trigger">Run a gate</a>`)+`<div id="message" class="message"></div><div class="grid three"><section class="card stat"><strong>${Object.keys(config.gates).length}</strong><span>configured gates</span></section><section class="card stat"><strong>${Object.keys(config.lab.devices).length}</strong><span>lab devices</span></section><section class="card stat"><strong>${Object.keys(config.lab.setups).length}</strong><span>test setups</span></section></div><section class="card" style="margin-top:18px"><h2>Recent gate runs</h2><table><thead><tr><th>Gate</th><th>Trigger</th><th>Commit</th><th>Status</th><th>Actions</th></tr></thead><tbody>${runRows()}</tbody></table></section><section class="card" id="archive-browser" style="margin-top:18px" hidden><h2>Local artifact archive</h2><div id="archive-list"></div><pre class="result" id="archive-result" hidden></pre></section><div class="grid three" style="margin-top:18px"><a class="card" href="/gates"><h3>Configure gates</h3><p>Repositories, test modules, triggers, schedules, and setup matrices.</p></a><a class="card" href="/lab"><h3>Manage the lab</h3><p>Hosts, devices, USB identity, photos, and setup roles.</p></a><a class="card" href="/trigger"><h3>Run a gate</h3><p>Queue a project revision on selected device types or approve an exact untrusted PR head.</p></a></div>`}
function repositoryForm(id,value={},create=false){return `<details ${create?'open':''}><summary>${create?'Add repository':esc(id+' · '+(value.repository||''))}</summary><form class="resource-form" data-kind="repository" data-path="repositories" data-id="${esc(id)}" data-create="${create}"><div class="fields">${field('Configuration ID','resource_id',id,'text',create?'required pattern="[a-z0-9][a-z0-9_-]*"':'readonly')}${field('GitHub repository','repository',value.repository||'','text','required placeholder="owner/name"')}${area('Push branches','push_branches',(value.pushes?.branches||[]).join('\n'),'One branch per line')}${area('PR base branches','base_branches',(value.pull_requests?.base_branches||[]).join('\n'),'One branch per line')}${area('Trusted contributors','trusted_contributors',(value.pull_requests?.trusted_contributors||[]).join('\n'),'Exact GitHub logins; unlisted PRs can still be approved one at a time.')}</div><div class="actions"><button type="submit">${create?'Create repository':'Save repository'}</button>${create?'':`<button class="danger" type="button" data-action="delete" data-path="repositories" data-id="${esc(id)}">Delete</button>`}</div></form></details>`}
function moduleForm(id,value={},create=false){return `<details ${create?'open':''}><summary>${create?'Add test module':esc(id+' · '+(value.pattern||''))}</summary><form class="resource-form" data-kind="module" data-path="test-modules" data-id="${esc(id)}" data-create="${create}"><div class="fields">${field('Configuration ID','resource_id',id,'text',create?'required pattern="[a-z0-9][a-z0-9_-]*"':'readonly')}${field('Test filename pattern','pattern',value.pattern||'','text','required')}${field('Runner profile override','runner_profile',value.runner_profile||'')}${field('Timeout seconds','timeout',value.timeout||'','number','min="1"')}${area('Compatible device types','device_types',(value.device_types||[]).join('\n'),'One device type per line')}${area('Required interfaces','required_interfaces',(value.required_interfaces||[]).join('\n'),'Examples: api, websocket, serial, usb')}</div><div class="actions"><button type="submit">${create?'Create module':'Save module'}</button>${create?'':`<button class="danger" type="button" data-action="delete" data-path="test-modules" data-id="${esc(id)}">Delete</button>`}</div></form></details>`}
function gateForm(id,value={},create=false){const repositories=Object.keys(config.repositories).map(key=>[key,`${key} · ${config.repositories[key].repository}`]);const modules=Object.keys(config.test_modules).map(key=>[key,key]);const setups=Object.keys(config.lab.setups).map(key=>[key,config.lab.setups[key].platform_key||key]);const schedules=(value.triggers?.schedules||[]).map(item=>`${item.id} | ${item.cron}`).join('\n');const deployment=value.deployment||{};return `<details ${create?'open':''}><summary>${create?'Create a gate':esc(id+' · '+(value.name||value.repository||''))}</summary><form class="resource-form" data-kind="gate" data-path="gates" data-id="${esc(id)}" data-create="${create}"><div class="fields">${field('Gate ID','resource_id',id,'text',create?'required pattern="[a-z0-9][a-z0-9_-]*"':'readonly')}${field('Display name','name',value.name||'')}${select('Repository','repository',repositories,value.repository||repositories[0]?.[0]||'','required')}${select('Required result policy','required', [['all','All assignments pass'],['any','At least one passes']],value.required||'all')}${checks('Triggers','trigger_flags',[['pushes','Pushes'],['pull_requests','Pull requests']],[...(value.triggers?.pushes!==false?['pushes']:[]),...(value.triggers?.pull_requests!==false?['pull_requests']:[])])}${area('Schedules','schedules',schedules,'One per line: schedule-id | five-field cron')}${checks('Test modules','test_modules',modules,value.test_modules||[])}${checks('Target setups','setups',setups,value.targets?.setups||[])}${area('Included paths','include_paths',(value.changes?.include||[]).join('\n'),'Glob patterns, one per line')}${area('Excluded paths','exclude_paths',(value.changes?.exclude||[]).join('\n'),'Glob patterns, one per line')}<div class="field full"><label class="check"><input type="checkbox" name="deploy_enabled" ${checked(Boolean(value.deployment))}> Deploy firmware before tests</label></div>${field('Artifact ID','artifact',deployment.artifact||'')}${area('Deployment device roles','device_roles',(deployment.device_roles||[]).join('\n'),'Setup roles, one per line')}${field('Reboot timeout seconds','reboot_timeout',deployment.reboot_timeout||180,'number','min="1"')}</div><div class="actions"><button type="submit">${create?'Create gate':'Save gate'}</button>${create?'':`<button class="secondary" type="button" data-action="validate-gate" data-id="${esc(id)}">Preview matrix</button><button class="danger" type="button" data-action="delete" data-path="gates" data-id="${esc(id)}">Delete</button>`}</div><pre class="result" id="gate-result-${esc(id)}" hidden></pre></form></details>`}
function renderGates(){if(config.coordination?.mode==='central'){const statusUrl=config.coordination.central.base_url.replace(/\/$/,'');app.innerHTML=pageHead('Central definitions','Projects, suites, gates, and trigger revisions are owned by Mining QA Status.',`<a class="button" href="${esc(statusUrl+'/projects')}" target="_blank" rel="noreferrer">Open Status projects</a>`)+`<section class="card"><h2>No local gate ownership</h2><p>This Lab subscribes to <strong>${esc((config.coordination.central.subscriptions?.gates||[]).join(', '))}</strong>. Portable definitions arrive frozen from Status and cannot merge with local repositories, modules, or gates.</p></section>`;return}app.innerHTML=pageHead('Gate setup','Configure local gates while retaining separate Status-owned shared definitions.')+hybridSharedCard()+`<div id="message" class="message"></div><section class="card"><h2>Local gates</h2><p>Choose triggers, tests, setups, schedules, path filters, and optional firmware deployment.</p>${Object.entries(config.gates).map(([id,value])=>gateForm(id,value)).join('')}${gateForm('',{},true)}</section><div class="grid two" style="margin-top:18px"><section class="card"><h2>Local repositories</h2><p>Define branches and contributor trust. One-off PR approvals live on the Run page.</p>${Object.entries(config.repositories).map(([id,value])=>repositoryForm(id,value)).join('')}${repositoryForm('',{},true)}</section><section class="card"><h2>Local test modules</h2><p>Map test patterns to compatible device types and required interfaces.</p>${Object.entries(config.test_modules).map(([id,value])=>moduleForm(id,value)).join('')}${moduleForm('',{},true)}</section></div>`}
function hostForm(id,value={},create=false){return `<details ${create?'open':''}><summary>${create?'Add host':esc(id+' · '+(value.transport||'local'))}</summary><form class="resource-form" data-kind="host" data-path="lab/hosts" data-id="${esc(id)}" data-create="${create}"><div class="fields">${field('Host ID','resource_id',id,'text',create?'required pattern="[a-z0-9][a-z0-9_-]*"':'readonly')}${select('Transport','transport',[['local','Local USB'],['ssh','Remote SSH']],value.transport||'local')}${field('SSH target','ssh_target',value.ssh_target||'','text','placeholder="user@host"')}${field('Maximum parallel tests','max_parallel',value.max_parallel||1,'number','min="1"')}${field('miner-test executable','miner_test',value.miner_test||'')}</div><div class="actions"><button type="submit">${create?'Create host':'Save host'}</button>${create?'':`<button class="secondary" type="button" data-action="probe-host" data-id="${esc(id)}">Probe host</button><button class="secondary" type="button" data-action="usb-host" data-id="${esc(id)}">Discover USB</button><button class="danger" type="button" data-action="delete" data-path="lab/hosts" data-id="${esc(id)}">Delete</button>`}</div><pre class="result" id="host-result-${esc(id)}" hidden></pre></form></details>`}
function deviceForm(id,value={},create=false){const hosts=Object.keys(config.lab.hosts).map(key=>[key,key]);return `<details ${create?'open':''}><summary>${create?'Add device':esc(id+' · '+(value.name||value.type||''))}</summary><form class="resource-form" data-kind="device" data-path="lab/devices" data-id="${esc(id)}" data-create="${create}"><div class="fields">${field('Device ID','resource_id',id,'text',create?'required pattern="[a-z0-9][a-z0-9_-]*"':'readonly')}${field('Device name','name',value.name||'','text','required')}${field('Adapter type','type',value.type||'','text','required')}${select('Owning host','host',hosts,value.host||hosts[0]?.[0]||'','required')}${field('API address','api',value.addresses?.api||'','url','placeholder="http://device.local"')}${field('WebSocket address','websocket',value.addresses?.websocket||'','url')}${field('USB serial path','serial_path',value.usb?.serial_path||'')}${field('USB vendor ID','vendor_id',value.usb?.vendor_id||'')}${field('USB product ID','product_id',value.usb?.product_id||'')}${field('USB serial number','serial_number',value.usb?.serial_number||'')}${field('Expected board version','board_version',value.expected?.board_version||'')}${area('Tags','tags',(value.tags||[]).join('\n'),'One tag per line')}<label class="field full"><span>Local photo</span><input name="photo" type="file" accept="image/jpeg,image/png,image/webp">${value.photo?`<span class="hint">Current: ${esc(value.photo)}</span>`:''}</label></div><div class="actions"><button type="submit">${create?'Create device':'Save device'}</button>${create?'':`<button class="secondary" type="button" data-action="probe-device" data-id="${esc(id)}">Probe device</button><button class="danger" type="button" data-action="delete" data-path="lab/devices" data-id="${esc(id)}">Delete</button>`}</div><pre class="result" id="device-result-${esc(id)}" hidden></pre></form></details>`}
function setupForm(id,value={},create=false){const hosts=Object.keys(config.lab.hosts).map(key=>[key,key]);const mappings=Object.entries(value.devices||{}).map(([role,device])=>`${role}=${device}`).join('\n');return `<details ${create?'open':''}><summary>${create?'Add setup':esc(id+' · '+(value.platform_key||''))}</summary><form class="resource-form" data-kind="setup" data-path="lab/setups" data-id="${esc(id)}" data-create="${create}"><div class="fields">${field('Setup ID','resource_id',id,'text',create?'required pattern="[a-z0-9][a-z0-9_-]*"':'readonly')}${select('Host','host',hosts,value.host||hosts[0]?.[0]||'','required')}${field('Platform key','platform_key',value.platform_key||'')}${field('Runner profile','runner_profile',value.runner_profile||'','text','required')}${area('Device roles','devices',mappings,'One per line: role=device-id')}</div><div class="actions"><button type="submit">${create?'Create setup':'Save setup'}</button>${create?'':`<button class="secondary" type="button" data-action="preflight" data-id="${esc(id)}">Run preflight</button><button class="danger" type="button" data-action="delete" data-path="lab/setups" data-id="${esc(id)}">Delete</button>`}</div><pre class="result" id="setup-result-${esc(id)}" hidden></pre></form></details>`}
function renderLab(){if(config.coordination?.mode==='central'){const bindings=Object.entries(config.bindings?.suite_requirements||{});app.innerHTML=pageHead('Private bindings','Review the local authorization that maps portable requirements to this Lab. Paths and device selectors remain private.')+`<div class="grid two">${bindings.map(([id,value])=>`<section class="card"><div class="eyebrow">${esc(value.execution)} binding</div><h2>${esc(id)}</h2><p>${esc(value.platform_class)} · ${esc(value.device_model)}</p><p><strong>Capabilities:</strong> ${esc((value.capabilities||[]).join(', '))}</p><p><strong>Resources:</strong> ${esc((value.resources||[]).join(', '))}</p><p><strong>Runner devices:</strong> ${esc((value.runner_devices||[]).join(', ')||'loopback mock')}</p><p><strong>Timeout:</strong> ${esc(value.timeout_seconds)} seconds</p></section>`).join('')||'<div class="empty">No private bindings configured.</div>'}</div>`;return}app.innerHTML=pageHead('Lab and device setup','Describe where devices live, how to identify them, and which devices form each runnable setup.')+`<div id="message" class="message"></div><div class="grid two"><section class="card"><h2>Hosts</h2><p>Use local transport or an SSH server that owns the USB connection.</p>${Object.entries(config.lab.hosts).map(([id,value])=>hostForm(id,value)).join('')}${hostForm('',{},true)}</section><section class="card"><h2>Setups</h2><p>Assign named device roles and a runner profile to a platform.</p>${Object.entries(config.lab.setups).map(([id,value])=>setupForm(id,value)).join('')}${setupForm('',{},true)}</section></div><section class="card" style="margin-top:18px"><h2>Devices</h2><p>Record addresses, stable USB identity, expected board identity, tags, and a local photo.</p>${Object.entries(config.lab.devices).map(([id,value])=>deviceForm(id,value)).join('')}${deviceForm('',{},true)}</section>`}
function renderTrigger(){if(config.coordination?.mode==='central'){const statusUrl=config.coordination.central.base_url.replace(/\/$/,'');app.innerHTML=pageHead('Central triggers','Manual trigger ownership is centralized. This Lab can accept or decline eligible work but cannot create or retarget it.',`<a class="button" href="${esc(statusUrl+'/triggers')}" target="_blank" rel="noreferrer">Run manually in Status</a>`)+`<section class="card"><h2>No Lab-owned manual gate</h2><p>Use Mining QA Status to choose an enabled trigger revision and exact source commit. This Lab will independently revalidate its private binding and leases before execution.</p></section>`;return}const repositories=Object.keys(config.repositories).map(id=>[id,`${id} · ${config.repositories[id].repository}`]);if(!manualRepository)manualRepository=repositories[0]?.[0]||'';let manualGates=Object.entries(config.gates).filter(([,gate])=>gate.repository===manualRepository).map(([id,gate])=>[id,gate.name||id]);if(!manualGates.some(([id])=>id===manualGate))manualGate=manualGates[0]?.[0]||'';const selectedGate=config.gates[manualGate];const setupIds=selectedGate?.targets?.setups||[];const deviceTypes=[...new Set(setupIds.flatMap(setupId=>Object.values(config.lab.setups[setupId]?.devices||{}).map(deviceId=>config.lab.devices[deviceId]?.type).filter(Boolean)))].sort();const branches=(config.repositories[manualRepository]?.pushes?.branches||[]).map(branch=>[branch,branch]);if(!pullRepository)pullRepository=repositories[0]?.[0]||'';const gates=Object.entries(config.gates).filter(([,gate])=>gate.repository===pullRepository&&gate.triggers?.pull_requests!==false).map(([id,gate])=>[id,gate.name||id]);const untrusted=(pullRequests||[]).filter(pr=>!pr.trusted);app.innerHTML=pageHead('Run gates','Queue a local lab gate for a configured project and device type. Detailed children and the parent gate still publish to Mining QA Status when configured.')+`<section class="card"><h2>Run a gate locally</h2><p>Leave commit blank to resolve the latest available configured <code>main</code>, then <code>master</code>, at submission time.</p><form class="manual-run-form"><div class="fields">${select('Project','manual_repository',repositories,manualRepository,'required')}${select('Gate','manual_gate',manualGates,manualGate,'required')}${select('Source branch','manual_branch',[['','Latest main/master (automatic)'],...branches],'')}${field('Commit SHA (optional)','manual_commit','','text','placeholder="Latest project main/master" pattern="[0-9a-fA-F]{40}"')}${checks('Device types','manual_device_types',deviceTypes.map(item=>[item,item]),deviceTypes)}</div><div class="actions"><button type="submit">Queue local gate</button></div><pre class="result" id="manual-run-result" hidden></pre></form><div id="message" class="message"></div></section><section class="card" style="margin-top:18px"><h2>Run an untrusted PR</h2><p>Review the exact GitHub head commit and explicitly assign a configured gate. This approval applies to one SHA only.</p><div class="fields">${select('Repository','pull_repository',repositories,pullRepository)}${select('Gate','pull_gate',gates,gates[0]?.[0]||'')}</div><div class="actions"><button class="secondary" type="button" data-action="load-prs">Refresh pull requests</button></div></section><div class="grid" style="margin-top:18px">${pullRequests===null?'<div class="empty">Loading open pull requests…</div>':untrusted.map(pr=>`<article class="card pr-card" data-pr="${pr.number}" data-sha="${esc(pr.head_sha)}"><a class="pr-title" href="${esc(pr.url)}" target="_blank" rel="noreferrer">#${pr.number} · ${esc(pr.title)}</a><div class="pr-meta"><span>@${esc(pr.contributor)}</span><span>${esc(pr.head_branch)} → ${esc(pr.base_branch)}</span><code>${esc(pr.head_sha.slice(0,12))}</code>${pr.draft?'<span class="pill warn">draft</span>':''}</div><div class="danger-note">This code is not from a trusted contributor. Confirm the PR and exact commit before giving it lab hardware.</div><label class="check" style="margin-top:14px"><input type="checkbox" name="approve"> I reviewed this PR and approve running this exact SHA</label><div class="actions"><button type="button" data-action="approve-pr">Queue selected gate</button></div><pre class="result" id="pr-result-${pr.number}" hidden></pre></article>`).join('')||'<div class="empty">No untrusted open pull requests target the watched base branches.</div>'}</div>`;if(pullRequests===null&&pullRepository)setTimeout(loadPullRequests,0)}
function renderAdvanced(){app.innerHTML=pageHead('Advanced configuration','The structured forms are preferred. Use raw YAML only for fields the forms do not expose.')+`<section class="card"><div id="message" class="message"></div><textarea id="yaml-editor" class="yaml">${esc(boot.yaml)}</textarea><div class="actions"><button type="button" data-action="save-yaml">Validate and save YAML</button><a class="button secondary" href="/docs">API documentation</a></div></section>`}
function render(){document.querySelectorAll('nav a').forEach(link=>link.classList.toggle('active',link.dataset.page===boot.page));if(boot.page==='gates')renderGates();else if(boot.page==='lab'){renderLab();if(config.coordination?.mode==='hybrid')document.querySelector('.page-head').insertAdjacentHTML('afterend',hybridSharedCard())}else if(boot.page==='trigger'){renderTrigger();neutralizeRunLanguage();document.querySelector('.manual-run-form .fields')?.insertAdjacentHTML('beforeend',localModuleControls());const prGrid=[...app.querySelectorAll('.grid')].at(-1);prGrid?.insertAdjacentHTML('beforebegin',pullRequestFilter());app.insertAdjacentHTML('beforeend',pullRequestPagination());if(config.coordination?.mode==='hybrid')document.querySelector('.page-head').insertAdjacentHTML('afterend',hybridSharedRunCard())}else if(boot.page==='advanced')renderAdvanced();else{renderOverview();if(config.coordination?.mode==='hybrid')document.querySelector('.page-head').insertAdjacentHTML('afterend',hybridSharedCard())}}
function repositoryValue(form,id){const value=clone(config.repositories[id]||{});value.repository=form.elements.repository.value.trim();value.pushes={...(value.pushes||{}),branches:lines(form.elements.push_branches.value)};value.pull_requests={...(value.pull_requests||{}),base_branches:lines(form.elements.base_branches.value),trusted_contributors:lines(form.elements.trusted_contributors.value)};return value}
function moduleValue(form,id){const value=clone(config.test_modules[id]||{});value.pattern=form.elements.pattern.value.trim();value.device_types=lines(form.elements.device_types.value);value.required_interfaces=lines(form.elements.required_interfaces.value);const profile=form.elements.runner_profile.value.trim();if(profile)value.runner_profile=profile;else delete value.runner_profile;const timeout=integer(form,'timeout');if(timeout)value.timeout=timeout;else delete value.timeout;return value}
function gateValue(form,id){const value=clone(config.gates[id]||{});value.repository=form.elements.repository.value;value.required=form.elements.required.value;const name=form.elements.name.value.trim();if(name)value.name=name;else delete value.name;value.triggers={...(value.triggers||{}),pushes:values(form,'trigger_flags').includes('pushes'),pull_requests:values(form,'trigger_flags').includes('pull_requests'),schedules:lines(form.elements.schedules.value).map(line=>{const split=line.indexOf('|');if(split<1)throw new Error(`Schedule must use id | cron: ${line}`);return{id:line.slice(0,split).trim(),cron:line.slice(split+1).trim()}})};value.test_modules=values(form,'test_modules');value.targets={...(value.targets||{}),setups:values(form,'setups')};const include=lines(form.elements.include_paths.value),exclude=lines(form.elements.exclude_paths.value);if(include.length||exclude.length)value.changes={include,exclude};else delete value.changes;if(form.elements.deploy_enabled.checked)value.deployment={...(value.deployment||{}),method:'esp_miner_http_ota',artifact:form.elements.artifact.value.trim(),device_roles:lines(form.elements.device_roles.value),reboot_timeout:integer(form,'reboot_timeout')||180};else delete value.deployment;return value}
function hostValue(form,id){const value=clone(config.lab.hosts[id]||{});value.transport=form.elements.transport.value;value.max_parallel=integer(form,'max_parallel')||1;const ssh=form.elements.ssh_target.value.trim(),miner=form.elements.miner_test.value.trim();if(value.transport==='ssh')value.ssh_target=ssh;else delete value.ssh_target;if(miner)value.miner_test=miner;else delete value.miner_test;return value}
function deviceValue(form,id){const value=clone(config.lab.devices[id]||{});value.name=form.elements.name.value.trim();value.type=form.elements.type.value.trim();value.host=form.elements.host.value;value.addresses={...(value.addresses||{})};for(const key of ['api','websocket']){const item=form.elements[key].value.trim();if(item)value.addresses[key]=item;else delete value.addresses[key]}value.usb={...(value.usb||{})};for(const key of ['serial_path','vendor_id','product_id','serial_number']){const item=form.elements[key].value.trim();if(item)value.usb[key]=item;else delete value.usb[key]}if(!Object.keys(value.usb).length)delete value.usb;value.expected={...(value.expected||{})};const board=form.elements.board_version.value.trim();if(board)value.expected.board_version=board;else delete value.expected.board_version;value.tags=lines(form.elements.tags.value);return value}
function setupValue(form,id){const value=clone(config.lab.setups[id]||{});value.host=form.elements.host.value;value.platform_key=form.elements.platform_key.value.trim();value.runner_profile=form.elements.runner_profile.value.trim();value.devices={};for(const line of lines(form.elements.devices.value)){const split=line.indexOf('=');if(split<1)throw new Error(`Device role must use role=device-id: ${line}`);value.devices[line.slice(0,split).trim()]=line.slice(split+1).trim()}return value}
async function submitResource(form){const create=form.dataset.create==='true';const id=create?form.elements.resource_id.value.trim():form.dataset.id;let value;if(form.dataset.kind==='repository')value=repositoryValue(form,id);else if(form.dataset.kind==='module')value=moduleValue(form,id);else if(form.dataset.kind==='gate')value=gateValue(form,id);else if(form.dataset.kind==='host')value=hostValue(form,id);else if(form.dataset.kind==='device')value=deviceValue(form,id);else value=setupValue(form,id);const photo=form.dataset.kind==='device'?form.elements.photo.files[0]:null;await saveResource(form.dataset.path,id,value,create);if(photo){await request(`/api/v1/lab/devices/${encodeURIComponent(id)}/photo`,{method:'PUT',mutate:true,headers:{'Content-Type':photo.type},body:photo})}render();setMessage(`${create?'Created':'Saved'} ${id}`)}
async function loadPullRequests(){pullRequests=null;allPullRequests=[];pullRequestPage=1;pullContributorFilter='';setMessage('Loading pull requests…');try{allPullRequests=(await request(`/api/v1/repositories/${encodeURIComponent(pullRepository)}/pull-requests`)).map(pr=>({...pr,trusted:false}));showPullRequestPage(1);setMessage(`Loaded ${allPullRequests.length} open pull requests`)}catch(error){pullRequests=[];allPullRequests=[];render();setMessage(error.message,true)}}
async function submitManual(form){const deviceTypes=values(form,'manual_device_types'),testModules=values(form,'manual_test_modules');if(!deviceTypes.length)throw new Error('Select at least one device type');if(!testModules.length)throw new Error('Select at least one test module');const run=await request(`/api/v1/gates/${encodeURIComponent(form.elements.manual_gate.value)}/run`,{method:'POST',mutate:true,etag:false,json:{repository_id:form.elements.manual_repository.value,branch:form.elements.manual_branch.value||null,commit_sha:form.elements.manual_commit.value.trim()||null,device_types:deviceTypes,test_modules:testModules}});showResult('manual-run-result',{queued:true,run_id:run.id,project:run.repository_id,gate_id:run.gate_id,commit_sha:run.commit_sha,branch:run.branch,device_types:deviceTypes,test_modules:testModules,status:run.status})}
async function submitShared(form){const kind=form.elements.shared_source_type.value,raw=form.elements.shared_source_value.value.trim(),testModules=values(form,'shared_test_modules');if(!raw)throw new Error('Enter a branch or pull request number');if(!testModules.length)throw new Error('Select at least one Testcode module');const source=kind==='branch'?{kind:'branch',branch:raw}:{kind:'pull_request',number:Number(raw)};if(kind==='pull_request'&&(!Number.isInteger(source.number)||source.number<1))throw new Error('Pull request number must be positive');const run=await request('/api/v1/central/manual-run',{method:'POST',mutate:true,etag:false,json:{gate_id:form.elements.shared_gate.value,source,test_modules:testModules}});showResult('shared-run-result',run)}
async function retryRun(button){const run=(boot.runs||[]).find(item=>item.id===button.dataset.id);if(!run)throw new Error('Gate run no longer appears in local history');if(!confirm(`Retry incomplete assignments for ${run.gate_id} at ${run.commit_sha}? Passed assignments will not run again.`))return;button.disabled=true;try{const updated=await request(`/api/v1/gate-runs/${encodeURIComponent(run.id)}/retry`,{method:'POST',mutate:true,etag:false});const index=boot.runs.findIndex(item=>item.id===updated.id);if(index>=0)boot.runs[index]={...updated,retryable:false};renderOverview();setMessage(`Retry queued for ${updated.gate_id} at ${updated.commit_sha.slice(0,12)}.`)}finally{if(button.isConnected)button.disabled=false}}
async function browseArtifacts(runId){const payload=await request(`/api/v1/gate-runs/${encodeURIComponent(runId)}/artifacts`,{mutate:true,etag:false});const browser=document.getElementById('archive-browser'),list=document.getElementById('archive-list');browser.hidden=false;list.innerHTML=payload.artifacts.length?`<table><thead><tr><th>Assignment</th><th>Attempt</th><th>Artifact</th><th>Size</th><th></th></tr></thead><tbody>${payload.artifacts.map(item=>`<tr><td>${esc(item.setup_id)} / ${esc(item.module_id)}</td><td>${esc(item.attempt)}</td><td><code>${esc(item.relative_path)}</code></td><td>${esc(item.size_bytes)} bytes</td><td><button class="secondary" type="button" data-action="view-artifact" data-run="${esc(runId)}" data-id="${esc(item.id)}">View</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No local artifacts were archived for this run.</div>';showResult('archive-result',{run_id:runId,artifacts:payload.artifacts.length})}
app.addEventListener('submit',event=>{const shared=event.target.closest('.shared-run-form');if(shared){event.preventDefault();submitShared(shared).catch(error=>setMessage(error.message,true));return}const manual=event.target.closest('.manual-run-form');if(manual){event.preventDefault();submitManual(manual).catch(error=>setMessage(error.message,true));return}const form=event.target.closest('.resource-form');if(!form)return;event.preventDefault();submitResource(form).catch(error=>setMessage(error.message,true))});
app.addEventListener('change',event=>{if(event.target.name==='pull_repository'){pullRepository=event.target.value;pullRequests=null;allPullRequests=[];pullRequestPage=1;pullContributorFilter='';render()}else if(event.target.name==='pr_contributor_filter'){pullContributorFilter=event.target.value;showPullRequestPage(1)}else if(event.target.name==='manual_repository'){manualRepository=event.target.value;manualGate='';render()}else if(event.target.name==='manual_gate'){manualGate=event.target.value;render()}});
app.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button?.dataset.action==='pr-prev')showPullRequestPage(pullRequestPage-1);else if(button?.dataset.action==='pr-next')showPullRequestPage(pullRequestPage+1)});
app.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;try{if(action==='pause-central'||action==='resume-central'){central=await request(`/api/v1/central/${action==='pause-central'?'pause':'resume'}`,{method:'POST',mutate:true,etag:false});renderOverview();setMessage(action==='pause-central'?'New central claims paused':'Central claims resumed')}else if(action==='delete')await deleteResource(button.dataset.path,button.dataset.id);else if(action==='validate-gate')showResult(`gate-result-${button.dataset.id}`,await request(`/api/v1/gates/${encodeURIComponent(button.dataset.id)}/validate`,{method:'POST',mutate:true,etag:false}));else if(action==='probe-host')showResult(`host-result-${button.dataset.id}`,await request(`/api/v1/lab/hosts/${encodeURIComponent(button.dataset.id)}/probe`,{method:'POST',mutate:true,etag:false}));else if(action==='usb-host')showResult(`host-result-${button.dataset.id}`,await request(`/api/v1/lab/hosts/${encodeURIComponent(button.dataset.id)}/usb`,{mutate:true,etag:false}));else if(action==='probe-device')showResult(`device-result-${button.dataset.id}`,await request(`/api/v1/lab/devices/${encodeURIComponent(button.dataset.id)}/probe`,{method:'POST',mutate:true,etag:false}));else if(action==='preflight')showResult(`setup-result-${button.dataset.id}`,await request(`/api/v1/lab/setups/${encodeURIComponent(button.dataset.id)}/preflight`,{method:'POST',mutate:true,etag:false}));else if(action==='retry-run')await retryRun(button);else if(action==='browse-artifacts')await browseArtifacts(button.dataset.id);else if(action==='view-artifact'){const payload=await request(`/api/v1/gate-runs/${encodeURIComponent(button.dataset.run)}/artifacts/${encodeURIComponent(button.dataset.id)}`,{mutate:true,etag:false});showResult('archive-result',`${payload.path}${payload.truncated?' (first 1 MiB)':''}\nSHA-256 ${payload.sha256}\n\n${payload.content}`)}else if(action==='load-prs')await loadPullRequests();else if(action==='approve-pr'){const card=button.closest('.pr-card'),gate=document.querySelector('[name="pull_gate"]').value,approval=card.querySelector('[name="approve"]');if(!gate)throw new Error('Select a pull-request gate');if(!approval.checked)throw new Error('Confirm the exact PR SHA before queuing');button.disabled=true;const run=await request(`/api/v1/repositories/${encodeURIComponent(pullRepository)}/pull-requests/${card.dataset.pr}/run`,{method:'POST',mutate:true,etag:false,json:{gate_id:gate,expected_sha:card.dataset.sha}});showResult(`pr-result-${card.dataset.pr}`,{queued:true,run_id:run.id,status:run.status,gate_id:run.gate_id,commit_sha:run.commit_sha,pr_number:run.pr_number});button.textContent='Queued'}else if(action==='save-yaml'){const editor=document.getElementById('yaml-editor'),source=editor.value;const payload=await request('/api/v1/config/yaml',{method:'PUT',mutate:true,headers:{'Content-Type':'application/yaml'},body:source});config=payload.config;boot.yaml=source;render();setMessage('Configuration saved')}}catch(error){setMessage(error.message,true)}});
render();
"""


def render_page(
    page: str,
    snapshot: Any,
    *,
    runs: list[Mapping[str, Any]] | None = None,
    central_status: Mapping[str, Any] | None = None,
) -> str:
    if page not in _TITLES:
        raise ValueError(f"unknown orchestrator UI page: {page}")
    payload = json.dumps(
        {
            "page": page,
            "config": snapshot.document,
            "revision": snapshot.revision,
            "etag": snapshot.etag,
            "runs": [
                {
                    **dict(run),
                    "retryable": run.get("status") in _RETRYABLE_RUN_STATUSES,
                }
                for run in (runs or [])
            ],
            "central": dict(central_status or {}),
            "yaml": yaml.safe_dump(snapshot.document, sort_keys=False),
        },
        separators=(",", ":"),
    ).replace("<", "\\u003c")
    navigation = "".join(
        f'<a data-page="{item}" href="{path}">{label}</a>'
        for item, path, label in (
            ("overview", "/", "Overview"),
            ("gates", "/gates", "Gates"),
            ("lab", "/lab", "Lab"),
            ("trigger", "/trigger", "Run gates"),
            ("advanced", "/config", "Advanced"),
        )
    )
    title = _TITLES[page]
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title} · Miner Test Orchestrator</title><style>{_STYLE}</style></head>
<body><header><div class="bar"><a class="brand" href="/">MINER<span>/LAB</span></a><nav aria-label="Primary">{navigation}</nav><span class="revision">config {snapshot.revision[:12]}</span></div></header>
<main id="app"><div class="page-head"><div><div class="eyebrow">Local control plane</div><h1>{title}</h1><p>Loading configuration forms…</p></div></div></main>
<noscript><main><p>This local control plane requires JavaScript for its configuration forms.</p></main></noscript>
<script id="bootstrap" type="application/json">{payload}</script><script>{_SCRIPT}</script></body></html>"""
